from itertools import product

# K_5 edges in lexicographic order of (i,j) for i<j
# Vertices: 0,1,2,3,4
edges = []
for i in range(5):
    for j in range(i+1, 5):
        edges.append((i,j))

print("Edges:", edges)
print("Edge indices:")
for idx, e in enumerate(edges):
    print(f"  c[{idx}] = edge {e}")

# Triangles in K_5
triangles = []
for i in range(5):
    for j in range(i+1, 5):
        for k in range(j+1, 5):
            triangles.append((i,j,k))

print("\nTriangles:", triangles)

# Edge index lookup
edge_idx = {e: idx for idx, e in enumerate(edges)}

def get_edge_idx(i, j):
    if i < j:
        return edge_idx[(i,j)]
    else:
        return edge_idx[(j,i)]

# Fixed assignments: c[3]=1, c[9]=0
# c[3] = edge (0,3), c[9] = edge (3,4)
print(f"\nFixed: c[3]=1 means edge {edges[3]} = 1 (blue)")
print(f"Fixed: c[9]=0 means edge {edges[9]} = 0 (red)")

# Try all 2^10 colorings
solutions = []
for coloring in product([0,1], repeat=10):
    # Check fixed assignments
    if coloring[3] != 1:
        continue
    if coloring[9] != 0:
        continue

    # Check no monochromatic triangle
    valid = True
    for (i,j,k) in triangles:
        e1 = get_edge_idx(i,j)
        e2 = get_edge_idx(i,k)
        e3 = get_edge_idx(j,k)
        c1, c2, c3 = coloring[e1], coloring[e2], coloring[e3]
        if c1 == c2 == c3:  # monochromatic triangle
            valid = False
            break

    if valid:
        solutions.append(coloring)

print(f"\nNumber of valid solutions: {len(solutions)}")
if solutions:
    print("First solution:", list(solutions[0]))
    for sol in solutions[:5]:
        print(list(sol))
